<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require BASE_PATH.'/app/AdminUi.php';$user=Auth::requireLogin();$type=$_GET['type']??'umrah';$isUmrah=$type==='umrah';Auth::requirePermission($isUmrah?'umrah.manage':'services.manage');$pdo=Database::connection();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){Security::verifyCsrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';$allowed=$isUmrah?['new','reviewing','quoted','confirmed','rejected','cancelled']:['new','reviewing','need_info','quoted','completed','rejected','cancelled'];if($id<1||!in_array($status,$allowed,true))$error='بيانات الحالة غير صحيحة.';else{$table=$isUmrah?'umrah_requests':'service_requests';$pdo->prepare("UPDATE {$table} SET status=? WHERE id=?")->execute([$status,$id]);admin_log($pdo,$user,'request.status_changed',$table,$id,'تغيير حالة الطلب إلى '.$status);}}
if($isUmrah)$rows=$pdo->query('SELECT r.id,r.reference_code,r.people_count,r.city,r.expected_date,r.status,r.created_at,c.full_name,c.phone,p.title item_title FROM umrah_requests r JOIN customers c ON c.id=r.customer_id LEFT JOIN umrah_programs p ON p.id=r.program_id ORDER BY r.id DESC LIMIT 500')->fetchAll();
else $rows=$pdo->query('SELECT r.id,r.reference_code,r.people_count,r.nationality,r.status,r.created_at,c.full_name,c.phone,s.title item_title FROM service_requests r JOIN customers c ON c.id=r.customer_id JOIN services s ON s.id=r.service_id ORDER BY r.id DESC LIMIT 500')->fetchAll();
admin_page_start('متابعة طلبات '.($isUmrah?'العمرة':'التأشيرات والزيارات'),$user);echo '<p><a class="admin-link" href="/admin/requests.php?type=umrah">طلبات العمرة</a> <a class="admin-link" href="/admin/requests.php?type=service">طلبات الخدمات</a></p>';if($error)echo '<p class="notice danger">'.e($error).'</p>';
echo '<section class="panel"><table><thead><tr><th>المرجع</th><th>العميل</th><th>الهاتف</th><th>البرنامج / الخدمة</th><th>الأشخاص</th><th>التاريخ</th><th>الحالة والإجراء</th></tr></thead><tbody>';
$statuses=$isUmrah?['new','reviewing','quoted','confirmed','rejected','cancelled']:['new','reviewing','need_info','quoted','completed','rejected','cancelled'];
foreach($rows as $r){echo '<tr><td>'.e($r['reference_code']).'</td><td>'.e($r['full_name']).'</td><td>'.e($r['phone']).'</td><td>'.e($r['item_title']??'طلب مخصص').'</td><td>'.(int)$r['people_count'].'</td><td>'.e($r['created_at']).'</td><td><form method="post" class="inline"><input type="hidden" name="_csrf" value="'.e(Security::csrf()).'"><input type="hidden" name="id" value="'.(int)$r['id'].'"><select name="status">';foreach($statuses as $s)echo '<option value="'.$s.'" '.($s===$r['status']?'selected':'').'>'.$s.'</option>';echo '</select><button class="btn-sm">تحديث</button></form></td></tr>';}
if(!$rows)echo '<tr><td colspan="7">لا توجد طلبات.</td></tr>';echo '</tbody></table></section>';admin_page_end();
